```java
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.regex.Pattern;

public class FlowerCategorizer {

    public static void main(String[] args) {
        String[] flowers = {"Lilac", "Daisy", "Marigold", "Chrysanthemum"};
        HashMap<String, List<String>> categories = new HashMap<>();

        Pattern categoryPattern = Pattern.compile("^((?:Li)|(?:Da)|(?:Ma)|(?:Ch))");

        for (String flower : flowers) {
            String category = categoryPattern.matcher(flower).replaceAll("$1");
            List<String> categoryList = categoriescomputeIfAbsent(category);
            categoryList.add(flower);
        }

        System.out.println(categories);
    }

    private static <K, V> List<V> categoriesComputeIfAbsent(K key) {
        List<V> categoryList = categories.get(key);
        if (categoryList == null) {
            categoryList = new ArrayList<>();
            categories.put(key, categoryList);
        }
        return categoryList;
    }

    private static final HashMap<String, List<String>> categories = new HashMap<>();
}
```

